// Arma el pedido a Gemini: instrucciones, historial corto y el mensaje (texto o audio)
const config = $('Config').first().json;
const body = $('Chat de Wally').first().json.body ?? {};

// Resistencia, Chaco (UTC-3, sin horario de verano). Siempre la hora real del servidor, nunca la del modelo
const tz = 'America/Argentina/Cordoba';
const ahora = new Date();
const hoy = new Intl.DateTimeFormat('en-CA', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit' }).format(ahora);
const hora = new Intl.DateTimeFormat('en-GB', { timeZone: tz, hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).format(ahora);
const fechaLarga = new Intl.DateTimeFormat('es-AR', { timeZone: tz, weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' }).format(ahora);

const instrucciones = [
  'Sos Wally, un asistente que anota los gastos e ingresos de una persona de Argentina.',
  'Ahora es ' + fechaLarga + ', ' + hora + ' hs (' + hoy + ', hora de Resistencia, Chaco, Argentina, UTC-3). Usá siempre esta fecha y hora como "ahora"; no supongas otra.',
  'Vas a recibir un mensaje de texto o un audio. Los audios pueden tener ruido y modismos: "lucas" o "luquitas" son miles, "palo" es un millón.',
  '',
  'Elegí una acción:',
  '- "guardar": el mensaje describe un gasto o ingreso y el monto está claro.',
  '- "preguntar": describe un movimiento pero falta el monto; preguntá solo lo que falta. Usá el historial para completar datos dichos antes.',
  '- "charlar": saludos u otra cosa; respondé breve y recordá que podés anotar gastos e ingresos.',
  '',
  'Campos del movimiento:',
  '- monto: número positivo, sin signos ni separadores de miles.',
  '- motivo: corto, qué fue (ej. "Supermercado", "Sueldo", "Nafta").',
  '- tipo: "gasto" o "ingreso".',
  '- categoria: una de ' + config.categorias + '.',
  '- fecha: YYYY-MM-DD. Resolvé "ayer", "anoche", "el viernes", "el 3", etc. respecto de ahora. Si no la dice, es hoy. Nunca una fecha futura salvo que lo diga explícitamente.',
  '- hora: HH:MM (24 hs) solo si dice cuándo fue ("a las 9", "al mediodía", "anoche" ≈ 22:00). Si no lo dice, vacío: se usa la hora actual si es hoy.',
  '- observacion: detalles extra que haya dicho (con quién, forma de pago, en cuotas, etc.). Vacío si no hay.',
  '',
  'transcripcion: si el mensaje es un audio, lo que dijo la persona, textual. Si es texto, vacío.',
  'respuesta: texto breve en español rioplatense (voseo) para mostrarle. Si guardás, confirmá en una línea, por ejemplo "Anoté $4.500 de Supermercado, hoy."',
].join('\n');

// Gemini necesita que la conversación empiece con el usuario
const historial = (Array.isArray(body.history) ? body.history : [])
  .filter((m) => m && typeof m.text === 'string' && m.text.trim())
  .slice(-10)
  .map((m) => ({ role: m.role === 'model' ? 'model' : 'user', parts: [{ text: m.text }] }));
while (historial.length && historial[0].role !== 'user') historial.shift();

let partes;
if (body.audio && body.audio.base64) {
  partes = [
    { inline_data: { mime_type: String(body.audio.mimeType || 'audio/webm').split(';')[0], data: body.audio.base64 } },
    { text: 'Audio de la persona.' },
  ];
} else if (typeof body.text === 'string' && body.text.trim()) {
  partes = [{ text: body.text.trim().slice(0, 2000) }];
} else {
  return [{ json: { vacio: true } }];
}

const texto = { type: 'STRING' };
const geminiRequest = {
  system_instruction: { parts: [{ text: instrucciones }] },
  contents: [...historial, { role: 'user', parts: partes }],
  generationConfig: {
    temperature: 0.2,
    responseMimeType: 'application/json',
    responseSchema: {
      type: 'OBJECT',
      properties: {
        accion: { type: 'STRING', enum: ['guardar', 'preguntar', 'charlar'] },
        transcripcion: texto,
        respuesta: texto,
        movimiento: {
          type: 'OBJECT',
          nullable: true,
          properties: {
            monto: { type: 'NUMBER' },
            motivo: texto,
            tipo: { type: 'STRING', enum: ['gasto', 'ingreso'] },
            categoria: texto,
            fecha: texto,
            hora: texto,
            observacion: texto,
          },
          required: ['monto', 'motivo', 'tipo', 'categoria', 'fecha', 'observacion'],
        },
      },
      required: ['accion', 'transcripcion', 'respuesta'],
    },
  },
};

return [{ json: { geminiRequest, hoy, hora, esAudio: !!(body.audio && body.audio.base64) } }];

// Lee la respuesta de Gemini y, si hay que guardar, arma la fila para Supabase
const res = $input.first().json;
const { hoy, hora: horaActual, esAudio } = $('Preparar pedido').first().json;
const error = (text) => [{ json: { accion: 'error', response: { text, status: 'error' } } }];

if (res.statusCode !== 200) {
  return error(res.statusCode === 429
    ? 'Llegué al límite de la IA por ahora. Probá de nuevo en un rato.'
    : 'No pude hablar con la IA. Revisá la credencial de Gemini en n8n.');
}

const raw = (res.body?.candidates?.[0]?.content?.parts ?? []).map((p) => p.text ?? '').join('');
let ia;
try {
  ia = JSON.parse(raw);
} catch {
  return error(esAudio ? 'No te entendí bien el audio. ¿Me lo repetís?' : 'No te entendí. ¿Me lo decís de otra forma?');
}

const transcript = esAudio ? (ia.transcripcion || '').trim() : '';
const m = ia.movimiento;
const monto = Math.round(Math.abs(Number(m?.monto)) * 100) / 100;

if (ia.accion !== 'guardar' || !m || !(monto > 0)) {
  // "guardar" without a usable amount is really a question
  const accion = ia.accion === 'guardar' ? 'preguntar' : (ia.accion || 'charlar');
  return [{ json: { accion, response: { text: ia.respuesta || '¿Qué querés anotar?', status: 'success', transcript } } }];
}

const fecha = /^\d{4}-\d{2}-\d{2}$/.test(m.fecha || '') ? m.fecha : hoy;
const motivo = (m.motivo || '').trim() || 'Sin motivo';
// Una hora futura de hoy es un error de la IA: se descarta
let hora = /^([01]\d|2[0-3]):[0-5]\d$/.test(m.hora || '') ? m.hora : '';
if (hora && fecha === hoy && hora > horaActual) hora = '';
const fila = {
  monto,
  descripcion: motivo.charAt(0).toUpperCase() + motivo.slice(1),
  tipo: m.tipo === 'ingreso' ? 'ingreso' : 'gasto',
  categoria: (m.categoria || 'otros').toLowerCase().trim() || 'otros',
  fecha,
  observacion: (m.observacion || '').trim(),
  // Los listados ordenan y agrupan por created_at, así que lleva el momento real del movimiento:
  // la hora que dijo; si no dijo, ahora (si es hoy) o el mediodía de ese día
  created_at: hora ? fecha + 'T' + hora + ':00-03:00' : (fecha === hoy ? new Date().toISOString() : fecha + 'T12:00:00-03:00'),
};

return [{ json: { accion: 'guardar', fila, response: { text: ia.respuesta, status: 'success', transcript } } }];

// Confirma lo guardado; si Supabase lo rechazó, avisa sin perder lo que dijo el usuario
const res = $input.first().json;
const previo = $('Interpretar').first().json.response;

if (res.statusCode !== 201) {
  return [{ json: { response: { text: 'Entendí el movimiento pero no lo pude guardar. Probá de nuevo.', status: 'error', transcript: previo.transcript } } }];
}

const guardado = Array.isArray(res.body) ? res.body[0] : res.body;
return [{ json: { response: { ...previo, saved: guardado } } }];
